import torch
import torch.nn as nn
import torch.nn.init as init
import math
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv_transpose2d_forward(torch::Tensor x,
                                        torch::Tensor weight,
                                        c10::optional<torch::Tensor> bias,
                                        int64_t stride_h, int64_t stride_w,
                                        int64_t pad_h, int64_t pad_w,
                                        int64_t dil_h, int64_t dil_w,
                                        int64_t groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

constexpr int CT_THREADS = 256;
constexpr int CT_PVEC    = 2;

template <typename T, int OcPerBlock>
__global__ void conv_transpose2d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ Bp,
    T* __restrict__ Y,
    int N, int Cin, int H, int Win,
    int Cout, int Hout, int Wout,
    int kH, int kW,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int groups, int icpg, int ocpg)
{
  const int tid = threadIdx.x;
  const int n = blockIdx.z;
  const int oc_tile = blockIdx.y;
  const int oc_base = oc_tile * OcPerBlock;
  const int group = oc_base / ocpg;
  const int ic_base = group * icpg;
  const int oc_in_group_base = oc_base - group * ocpg;

  const int P_total = Hout * Wout;
  const int PTile = CT_THREADS * CT_PVEC;
  const int p_block = blockIdx.x * PTile;

  const int64_t sXn = (int64_t)Cin * H * Win;
  const int64_t sYn = (int64_t)Cout * Hout * Wout;

  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, H, Win),
      make_stride((int64_t)H * Win, (int64_t)Win, (int64_t)1));

  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Hout, Wout),
      make_stride((int64_t)Hout * Wout, (int64_t)Wout, (int64_t)1));

  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cin, ocpg, kH, kW),
      make_stride((int64_t)ocpg * kH * kW, (int64_t)kH * kW, (int64_t)kW, (int64_t)1));

  extern __shared__ unsigned char smem_raw[];
  T* sW_ptr = reinterpret_cast<T*>(smem_raw);
  auto sW = make_tensor(
      make_smem_ptr(sW_ptr),
      make_shape(OcPerBlock, icpg, kH, kW),
      make_stride(icpg * kH * kW, kH * kW, kW, 1));

  const int total_w = OcPerBlock * icpg * kH * kW;
  for (int idx = tid; idx < total_w; idx += CT_THREADS) {
    int rem = idx;
    int kw = rem % kW; rem /= kW;
    int kh = rem % kH; rem /= kH;
    int icc = rem % icpg; rem /= icpg;
    int occ = rem;
    int ic = ic_base + icc;
    int oc_in_group = oc_in_group_base + occ;
    T wval = T(0);
    if (ic < Cin && oc_in_group < ocpg) {
      wval = mW(ic, oc_in_group, kh, kw);
    }
    sW(occ, icc, kh, kw) = wval;
  }
  __syncthreads();

  int p_idx[CT_PVEC];
  int oh_arr[CT_PVEC];
  int ow_arr[CT_PVEC];

  #pragma unroll
  for (int i = 0; i < CT_PVEC; ++i) {
    int p = p_block + tid + i * CT_THREADS;
    p_idx[i] = p;
    if (p < P_total) {
      oh_arr[i] = p / Wout;
      ow_arr[i] = p - oh_arr[i] * Wout;
    } else {
      oh_arr[i] = 0;
      ow_arr[i] = 0;
    }
  }

  float acc[OcPerBlock][CT_PVEC];
  #pragma unroll
  for (int occ = 0; occ < OcPerBlock; ++occ) {
    int oc = oc_base + occ;
    float bval = 0.0f;
    if (Bp != nullptr && oc < Cout) bval = (float)Bp[oc];
    #pragma unroll
    for (int i = 0; i < CT_PVEC; ++i) acc[occ][i] = bval;
  }

  #pragma unroll
  for (int i = 0; i < CT_PVEC; ++i) {
    int p = p_idx[i];
    if (p >= P_total) continue;
    int oh = oh_arr[i];
    int ow = ow_arr[i];

    for (int kh = 0; kh < kH; ++kh) {
      int ih_num = oh + pad_h - kh * dil_h;
      if (ih_num % stride_h != 0) continue;
      int ih = ih_num / stride_h;
      if (ih < 0 || ih >= H) continue;

      for (int kw = 0; kw < kW; ++kw) {
        int iw_num = ow + pad_w - kw * dil_w;
        if (iw_num % stride_w != 0) continue;
        int iw = iw_num / stride_w;
        if (iw < 0 || iw >= Win) continue;

        #pragma unroll 1
        for (int icc = 0; icc < icpg; ++icc) {
          int ic = ic_base + icc;
          float xval = (float)mX(ic, ih, iw);
          #pragma unroll
          for (int occ = 0; occ < OcPerBlock; ++occ) {
            acc[occ][i] += xval * (float)sW(occ, icc, kh, kw);
          }
        }
      }
    }
  }

  #pragma unroll
  for (int occ = 0; occ < OcPerBlock; ++occ) {
    int oc = oc_base + occ;
    if (oc >= Cout) continue;
    #pragma unroll
    for (int i = 0; i < CT_PVEC; ++i) {
      int p = p_idx[i];
      if (p >= P_total) continue;
      mY(oc, oh_arr[i], ow_arr[i]) = static_cast<T>(acc[occ][i]);
    }
  }
}

torch::Tensor conv_transpose2d_forward(torch::Tensor x,
                                        torch::Tensor weight,
                                        c10::optional<torch::Tensor> bias,
                                        int64_t stride_h, int64_t stride_w,
                                        int64_t pad_h, int64_t pad_w,
                                        int64_t dil_h, int64_t dil_w,
                                        int64_t groups) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
  TORCH_CHECK(x.dim() == 4, "x must be [N,Cin,H,W]");
  TORCH_CHECK(weight.dim() == 4, "weight must be [Cin, Cout/groups, kH, kW]");

  auto x_c = x.contiguous();
  auto w_c = weight.contiguous();

  int64_t N = x_c.size(0);
  int64_t Cin = x_c.size(1);
  int64_t H = x_c.size(2);
  int64_t Win = x_c.size(3);

  int64_t ocpg = w_c.size(1);
  int64_t kH = w_c.size(2);
  int64_t kW = w_c.size(3);
  TORCH_CHECK(w_c.size(0) == Cin, "weight.size(0) must equal Cin");

  int64_t Cout = ocpg * groups;
  int64_t icpg = Cin / groups;
  TORCH_CHECK(icpg * groups == Cin, "Cin must be divisible by groups");

  int64_t Hout = (H - 1) * stride_h - 2 * pad_h + dil_h * (kH - 1) + 1;
  int64_t Wout = (Win - 1) * stride_w - 2 * pad_w + dil_w * (kW - 1) + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size computed");

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (bias.has_value()) {
    b_c = bias.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Hout, Wout}, x.options());

  constexpr int Threads = 256;
  constexpr int PVec = 2;
  const int64_t P_total = Hout * Wout;
  const int64_t PTile = Threads * PVec;

  bool use4 = (ocpg % 4 == 0);
  int OcPerBlock = use4 ? 4 : 1;

  dim3 block(Threads);
  dim3 grid(
      (unsigned)((P_total + PTile - 1) / PTile),
      (unsigned)((Cout + OcPerBlock - 1) / OcPerBlock),
      (unsigned)N
  );

  size_t shmem_bytes = (size_t)OcPerBlock * (size_t)icpg * (size_t)kH * (size_t)kW * sizeof(float);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  if (use4) {
    conv_transpose2d_kernel<float, 4><<<grid, block, shmem_bytes, stream>>>(
        x_c.data_ptr<float>(), w_c.data_ptr<float>(), b_ptr, y.data_ptr<float>(),
        (int)N, (int)Cin, (int)H, (int)Win,
        (int)Cout, (int)Hout, (int)Wout,
        (int)kH, (int)kW,
        (int)stride_h, (int)stride_w,
        (int)pad_h, (int)pad_w,
        (int)dil_h, (int)dil_w,
        (int)groups, (int)icpg, (int)ocpg);
  } else {
    conv_transpose2d_kernel<float, 1><<<grid, block, shmem_bytes, stream>>>(
        x_c.data_ptr<float>(), w_c.data_ptr<float>(), b_ptr, y.data_ptr<float>(),
        (int)N, (int)Cin, (int)H, (int)Win,
        (int)Cout, (int)Hout, (int)Wout,
        (int)kH, (int)kW,
        (int)stride_h, (int)stride_w,
        (int)pad_h, (int)pad_w,
        (int)dil_h, (int)dil_w,
        (int)groups, (int)icpg, (int)ocpg);
  }

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv_transpose2d_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

conv_transpose2d_ext = load_inline(
    name="cute_conv_transpose2d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv_transpose2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    2D transposed convolution (grouped, padded, dilated, asymmetric) implemented
    with a single custom CUDA kernel written using CuTe tensors.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: tuple = (1, 1), padding: tuple = (0, 0),
                 dilation: tuple = (1, 1), groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups

        assert in_channels % groups == 0
        assert out_channels % groups == 0

        kH, kW = kernel_size
        ocpg = out_channels // groups

        # Weight layout matches PyTorch ConvTranspose2d: (in_channels, out_channels/groups, kH, kW)
        self.weight = nn.Parameter(torch.empty(in_channels, ocpg, kH, kW))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv_transpose2d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            icpg = self.in_channels // self.groups
            kH, kW = self.kernel_size
            fan_in = icpg * kH * kW
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv_transpose2d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            int(self.stride[0]), int(self.stride[1]),
            int(self.padding[0]), int(self.padding[1]),
            int(self.dilation[0]), int(self.dilation[1]),
            int(self.groups),
        )

